const chatLogs = $('Read ChatLogs Sheet').all();
const tickets = $('Read Tickets Sheet').all();

const todayStr = new Date().toISOString().slice(0,10);

function isToday(dateVal) {
  if (!dateVal) return false;
  const d = new Date(dateVal);
  if (isNaN(d)) return false;
  return d.toISOString().slice(0,10) === todayStr;
}

const validLogs = chatLogs.filter(item => item.json['Timestamp']);
const validTickets = tickets.filter(item => item.json['Ticket ID']);

const todayLogs = validLogs.filter(item => isToday(item.json['Timestamp']));
const todayTickets = validTickets.filter(item => isToday(item.json['Created Date']));

const totalMessages = todayLogs.length;

const intentCounts = {};
todayLogs.forEach(item => {
  const intent = item.json['Intent'] || 'Unknown';
  intentCounts[intent] = (intentCounts[intent] || 0) + 1;
});

let mostCommonIntent = 'N/A';
let maxCount = 0;
for (const [intent, count] of Object.entries(intentCounts)) {
  if (count > maxCount) { maxCount = count; mostCommonIntent = intent; }
}

const ticketsCreatedToday = todayTickets.length;
const openTickets = validTickets.filter(item => (item.json['Status'] || '').toLowerCase() === 'open').length;
const resolvedTickets = validTickets.filter(item => (item.json['Status'] || '').toLowerCase() === 'resolved').length;
const highPriorityToday = todayTickets.filter(item => item.json['Priority'] === 'High').length;

const intentSummaryLines = Object.entries(intentCounts)
  .sort((a,b) => b[1]-a[1])
  .map(([intent,count]) => `- ${intent}: ${count}`)
  .join('\n') || 'No messages today';

return [{
  json: {
    todayStr,
    totalMessages,
    mostCommonIntent,
    ticketsCreatedToday,
    openTickets,
    resolvedTickets,
    highPriorityToday,
    intentSummaryLines
  }
}];

